test("final emitted output and UTF-8 accounting survive history reload", () => {
  const tracker = new ContextPruningTracker(root);
  const first = run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(third.output).toContain("callId: first");
  expect(tracker.getHistory().map(r => r.prunedOutput)).toEqual([null, second.output, third.output]);
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory().every(r => r.originalOutput === output)).toBe(true);
  expect(tracker.getStats()).toEqual({
    totalCalls: 3,
    prunedCalls: 2,
    totalBytesSaved: second.bytesSaved + third.bytesSaved,
    estimatedContextBytes: [first, second, third].reduce((n, r) => n + Buffer.byteLength(r.output), 0),
  });
  const reloaded = new ContextPruningTracker(root);
  reloaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(reloaded.getStats()).toEqual(tracker.getStats());
  expect(run(reloaded, "fourth").output).toContain("callId: first");
});

